import gurobipy as gp

def main():
    # data
    c = [[4, 9, 2, 6, 5],
         [2, 6, 1, 7, 9],
         [2, 4, 9, 8, 3]]
    d = [15, 35, 20, 5, 40]
    cap = [60, 30, 45]

    env = None
    model = gp.Model(env=env)

    x = {}
    for i in range(3):
        for j in range(5):
            x[(i, j)] = model.addVar(lb=0, vtype="cont", name=f"x_{i+1}_{j+1}")

    # objective
    obj_expr = gp.LinExpr()
    for i in range(3):
        for j in range(5):
            obj_expr += c[i][j] * x[(i, j)]
    model.setObjective(obj_expr, gp.GRB.MINIMIZE)

    # demand constraints
    for j in range(5):
        expr = gp.LinExpr()
        for i in range(3):
            expr += x[(i, j)]
        model.addConstr(expr == d[j], name=f"demand_{j+1}")

    # capacity constraints
    for i in range(3):
        expr = gp.LinExpr()
        for j in range(5):
            expr += x[(i, j)]
        model.addConstr(expr <= cap[i], name=f"cap_{i+1}")

    # optimize
    status = model.optimize()

    # if optimal, print FINAL_OBJECTIVE
    if status == gp.GRB.OPTIMAL:
        obj_val = model.objvalue
        print(f"FINAL_OBJECTIVE={obj_val}")

if __name__ == "__main__":
    main()

