import gurobipy as gp

def main():
    # flight time matrix (minutes), symmetric, diagonal zero
    t = [
        [0, 8, 12, 15, 7, 10, 14],   # depot (index 0)
        [8, 0, 5, 11, 6, 9, 13],    # c1 (1)
        [12, 5, 0, 7, 10, 4, 8],   # c2 (2)
        [15, 11, 7, 0, 9, 6, 5],   # c3 (3)
        [7, 6, 10, 9, 0, 3, 11],   # c4 (4)
        [10, 9, 4, 6, 3, 0, 7],    # c5 (5)
        [14, 13, 8, 5, 11, 7, 0]   # c6 (6)
    ]

    N = list(range(7))          # {0=depot,1..6=customers}
    J = list(range(1, 7))      # {1..6}

    env = None
    model = gp.Model(env=env)

    # binary variables x[i][j] for i != j
    x = {}
    for i in N:
        for j in N:
            if i == j:
                continue
            x[(i, j)] = model.addVar(type='B', name=f"x_{i}_{j}")

    # integer variables u: depot fixed to 0, customers 0..5
    u_depot = model.addVar(type='I', lb=0, ub=0, name="u_d")   # forced to 0
    u = {}
    for k in J:
        u[k] = model.addVar(type='I', lb=0, ub=5, name=f"u_{k}")

    # objective: minimize total flight time
    obj_expr = gp.LinExpr()
    for i in N:
        for j in N:
            if i == j:
                continue
            obj_expr += t[i][j] * x[(i, j)]
    model.setObjective(obj_expr, gp.GRB.MINIMIZE)

    # out‑degree constraint: each node has exactly one outgoing edge
    for i in N:
        expr = gp.LinExpr()
        for j in N:
            if i == j:
                continue
            expr += x[(i, j)]
        model.addConstr(expr == 1, name=f"outdeg_{i}")

    # Miller–Tucker–Zemlin subtour elimination for customers only
    for i in J:
        for k in J:
            if i == k:
                continue
            expr = u[i] - u[k] + 6 * x[(i, k)]
            model.addConstr(expr <= 5, name=f"mtz_{i}_{k}")

    # depot start is enforced by fixing u_depot = 0 (bounds already force it)

    # solve the MIP
    model.optimize()

    # print FINAL_OBJECTIVE only if an optimal solution is found
    if model.Status == gp.GRB.OPTIMAL:
        obj_val = int(round(model.objval))
        print(f"FINAL_OBJECTIVE={obj_val}")

if __name__ == "__main__":
    main()
```

