import gurobipy as gp
from gurobipy import GRB

# Parameters
c_p = {'C': 350, 'J': 400, 'L': 300}
c_proc = {'C': 100, 'J': 80, 'L': 150}
avail = {'C': 1000, 'J': 800, 'L': 600}
f = {'OC': 0.7, 'JF': 0.75, 'LF': 0.8}
req = {'OC': 300, 'JF': 400, 'LF': 200}

# Eligibility sets (fabric -> raw)
E_OC = ['C', 'J']
E_JF = ['J', 'L']
E_LF = ['C', 'J', 'L']
E = {'OC': E_OC, 'JF': E_JF, 'LF': E_LF}

model = gp.Model(env=env)

# Create variables for eligible pairs
vars = {}
for F in ['OC', 'JF', 'LF']:
    for R in E[F]:
        vars[(R, F)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"{R}_{F}")

# Availability constraints
for R in ['C', 'J', 'L']:
    expr = gp.LinExpr()
    for F in ['OC', 'JF', 'LF']:
        if R in E[F]:
            expr += vars[(R, F)]
    model.addConstr(expr <= avail[R], name=f"avail_{R}")

# Production requirement constraints
for F in ['OC', 'JF', 'LF']:
    coeff = f[F]  # fraction of raw that becomes fabric
    expr = gp.LinExpr()
    for R in E[F]:
        expr += coeff * vars[(R, F)]
    model.addConstr(expr >= req[F], name=f"prod_{F}")

# Objective: minimize sum (c_p[R] + c_proc[R]) * u_{R,F} over eligible pairs
obj_expr = gp.LinExpr()
for F in ['OC', 'JF', 'LF']:
    for R in E[F]:
        obj_expr += (c_p[R] + c_proc[R]) * vars[(R, F)]
model.setObjective(obj_expr, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

