import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

cap = {'S1': 200, 'S2': 150, 'S3': 180}
d = {'D1': 120, 'D2': 90, 'D3': 110, 'D4': 130}
c_sh = {('S1', 'H1'): 5, ('S1', 'H2'): 7,
        ('S2', 'H1'): 6, ('S2', 'H2'): 8,
        ('S3', 'H1'): 4, ('S3', 'H2'): 5}
c_hd = {('H1', 'D1'): 3, ('H1', 'D2'): 4, ('H1', 'D3'): 5, ('H1', 'D4'): 6,
        ('H2', 'D1'): 4, ('H2', 'D2'): 3, ('H2', 'D3'): 6, ('H2', 'D4'): 5}

# supply arc variables x_{i,h}
x = {}
for i in ['S1', 'S2', 'S3']:
    for h in ['H1', 'H2']:
        key = (i, h)
        x[key] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"x_{i}_{h}")

# hub-to-demand variables y_{h,j}
y = {}
for h in ['H1', 'H2']:
    for j in ['D1', 'D2', 'D3', 'D4']:
        key = (h, j)
        y[key] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"y_{h}_{j}")

# constraint (1): supply capacity per source i
for i in ['S1', 'S2', 'S3']:
    expr = gp.quicksum([x[(i, h)] for h in ['H1', 'H2']])
    model.addConstr(expr <= cap[i], name=f"supply_{i}")

# constraint (2): demand requirement per demand j >= d_j
for j in ['D1', 'D2', 'D3', 'D4']:
    expr = gp.quicksum([y[(h, j)] for h in ['H1', 'H2']])
    model.addConstr(expr >= d[j], name=f"demand_{j}")

# constraint (3): flow balance per hub h
for h in ['H1', 'H2']:
    expr_in = gp.quicksum([x[(i, h)] for i in ['S1', 'S2', 'S3']])
    expr_out = gp.quicksum([y[(h, j)] for j in ['D1', 'D2', 'D3', 'D4']])
    model.addConstr(expr_in == expr_out, name=f"balance_{h}")

# objective: minimize total transportation cost
obj = gp.quicksum([c_sh[(i, h)] * x[(i, h)] for i in ['S1', 'S2', 'S3'] for h in ['H1', 'H2']]) \
      + gp.quicksum([c_hd[(h, j)] * y[(h, j)] for h in ['H1', 'H2'] for j in ['D1', 'D2', 'D3', 'D4']])
model.setObjective(obj, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

