    model.addConstr(expr >= d[j], name=f"demand_{j}")

# constraint (3): flow balance per hub h
for h in ['H1', 'H2']:
    expr_in = gp.quicksum([x[(i, h)] for i in ['S1', 'S2', 'S3']])
    expr_out = gp.quicksum([y[(h, j)] for j in ['D1', 'D2', 'D3', 'D4']])
    model.addConstr(expr_in == expr_out, name=f"balance_{h}")

# objective: minimize total transportation cost
obj = gp.quicksum([c_sh[(i, h)] * x[(i, h)] for i in ['S1', 'S2', 'S3'] for h in ['H1', 'H2']]) \
      + gp.quicksum([c_hd[(h, j)] * y[(h, j)] for h in ['H1', 'H2'] for j in ['D1', 'D2', 'D3', 'D4']])
model.setObjective(obj, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")

import gurobipy as gp
from gurobipy import GRB

# data
p = [4, 5, 3, 6, 2, 5, 4, 3]
e = []
for i in range(8):
    if (i + 1) in {2, 5}:
        e.append(2 * p[i])
    else:
        e.append(p[i])
cap = [15, 18, 12]
cost = [30, 25, 35]

model = gp.Model(env=env)

a = {}
for i in range(8):
    for j in range(3):
        a[(i, j)] = model.addVar(lb=0, ub=1, vtype=GRB.INTEGER, name=f"a_{i}_{j}")

# assignment constraints
for i in range(8):
    model.addConstr(gp.quicksum(a[(i, j)] for j in range(3)) == 1, name=f"assign_{i}")

# capacity constraints
for j in range(3):
    model.addConstr(gp.quicksum(e[i] * a[(i, j)] for i in range(8)) <= cap[j], name=f"cap_{j}")

# objective
obj = gp.quicksum(cost[j] * e[i] * a[(i, j)] for i in range(8) for j in range(3))
model.setObjective(obj, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
